int check_color(const char *color) {
    if (strcmp(color, "green") == 0 ||
        strcmp(color, "red") == 0 ||
        strcmp(color, "blue") == 0 ||
        strcmp(color, "white") == 0 ||
        strcmp(color, "yellow") == 0 ||
        strcmp(color, "cyan") == 0 ||
        strcmp(color, "magenta") == 0 ||
        strcmp(color, "black") == 0) {
        return 1;
    }
    return 0;
}

int check_delay(int delay) {
    return delay >= 0 && delay <= 10;
}
