#include "options.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Initialize options with default values
void options_init(Options *opts) {
    opts->async_scroll = false;
    opts->bold_chars = false;
    opts->all_bold = false;
    opts->force_term = false;
    opts->linux_mode = false;
    opts->old_scroll = false;
    opts->shadows_only = false;
    opts->lock_mode = false;
    opts->rainbow_mode = false;
    opts->lambda_mode = false;
    opts->chars_change = false;
    opts->x_window = false;
    opts->screensaver = false;
    opts->no_bold = true;
    opts->help_flag = false;
    opts->version_flag = false;
    opts->update_delay = 4;
    opts->color = "green";
    opts->message = NULL;
    opts->tty = NULL;
}

// Validate color string
bool options_validate_color(const char *color) {
    if (color == NULL) {
        return false;
    }
    const char *valid_colors[] = {"green", "red", "blue", "white", "yellow", "cyan", "magenta", "black", NULL};
    for (int i = 0; valid_colors[i] != NULL; i++) {
        if (strcmp(color, valid_colors[i]) == 0) {
            return true;
        }
    }
    return false;
}

// Validate update delay
bool options_validate_delay(int delay) {
    return delay >= 0 && delay <= 10;
}

// Print usage information
void options_print_usage(const char *progname) {
    printf(" Usage: %s -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n", progname);
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

// Print version information
void options_print_version(void) {
    printf(" CMatrix version 2.0 (compiled 22:13:51, Jun 11 2026)\n");
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

// Parse command-line arguments
int options_parse(int argc, char **argv, Options *opts) {
    if (argc < 1 || argv[0] == NULL) {
        return -1;
    }

    const char *progname = argv[0];

    // Check for --help or -h/-?
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0 || 
            strcmp(argv[i], "-h") == 0 || 
            strcmp(argv[i], "-?") == 0) {
            opts->help_flag = true;
            options_print_usage(progname);
            return 0;
        }
        if (strcmp(argv[i], "--version") == 0 || strcmp(argv[i], "-V") == 0) {
            opts->version_flag = true;
            options_print_version();
            return 0;
        }
    }

    // Parse other options
    for (int i = 1; i < argc; i++) {
        if (argv[i][0] != '-') {
            // Unknown option or positional argument
            options_print_usage(progname);
            return -1;
        }

        if (strcmp(argv[i], "-a") == 0) {
            opts->async_scroll = true;
        } else if (strcmp(argv[i], "-b") == 0) {
            opts->bold_chars = true;
        } else if (strcmp(argv[i], "-B") == 0) {
            opts->all_bold = true;
        } else if (strcmp(argv[i], "-c") == 0) {
            opts->shadows_only = true;
        } else if (strcmp(argv[i], "-f") == 0) {
            opts->force_term = true;
        } else if (strcmp(argv[i], "-l") == 0) {
            opts->linux_mode = true;
        } else if (strcmp(argv[i], "-L") == 0) {
            opts->lock_mode = true;
        } else if (strcmp(argv[i], "-o") == 0) {
            opts->old_scroll = true;
        } else if (strcmp(argv[i], "-n") == 0) {
            opts->no_bold = true;
        } else if (strcmp(argv[i], "-r") == 0) {
            opts->rainbow_mode = true;
        } else if (strcmp(argv[i], "-m") == 0) {
            opts->lambda_mode = true;
        } else if (strcmp(argv[i], "-k") == 0) {
            opts->chars_change = true;
        } else if (strcmp(argv[i], "-s") == 0) {
            opts->screensaver = true;
        } else if (strcmp(argv[i], "-x") == 0) {
            opts->x_window = true;
        } else if (strcmp(argv[i], "-u") == 0) {
            if (i + 1 >= argc) {
                options_print_usage(progname);
                return -1;
            }
            int delay = atoi(argv[++i]);
            if (!options_validate_delay(delay)) {
                printf("Error: update delay must be between 0 and 10\n");
                return -1;
            }
            opts->update_delay = delay;
        } else if (strcmp(argv[i], "-C") == 0) {
            if (i + 1 >= argc) {
                options_print_usage(progname);
                return -1;
            }
            opts->color = argv[++i];
            if (!options_validate_color(opts->color)) {
                printf(" Invalid color selection\n");
                printf(" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                return -1;
            }
        } else if (strcmp(argv[i], "-M") == 0) {
            if (i + 1 >= argc) {
                options_print_usage(progname);
                return -1;
            }
            opts->message = argv[++i];
        } else if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 >= argc) {
                options_print_usage(progname);
                return -1;
            }
            opts->tty = argv[++i];
        } else {
            // Unknown option
            options_print_usage(progname);
            return -1;
        }
    }

    return 0;
}
EOF"}

