+#ifndef OPTIONS_H
+#define OPTIONS_H
+
+#include <stdbool.h>
+
+// Option structure to hold parsed command-line options
+typedef struct {
+    bool async_scroll;        // -a
+    bool bold_chars;          // -b
+    bool all_bold;            // -B
+    bool force_term;          // -f
+    bool linux_mode;          // -l
+    bool old_scroll;          // -o
+    bool shadows_only;        // -c
+    bool lock_mode;           // -L
+    bool rainbow_mode;        // -r
+    bool lambda_mode;         // -m
+    bool chars_change;        // -k
+    bool x_window;            // -x
+    bool screensaver;         // -s
+    bool no_bold;             // -n
+    bool help_flag;           // -h, -?
+    bool version_flag;        // -V
+    
+    int update_delay;         // -u (default 4)
+    char *color;              // -C (default "green")
+    char *message;            // -M
+    char *tty;                // -t
+} Options;
+
+// Initialize options with default values
+void options_init(Options *opts);
+
+// Parse command-line arguments
+int options_parse(int argc, char **argv, Options *opts);
+
+// Print usage information
+void options_print_usage(const char *progname);
+
+// Print version information
+void options_print_version(void);
+
+// Validate color string
+bool options_validate_color(const char *color);
+
+// Validate update delay
+bool options_validate_delay(int delay);
+
+#endif // OPTIONS_H

