+#ifndef OPTIONS_H
+#define OPTIONS_H
+
+#include <stdio.h>
+
+typedef struct {
+    int async_scroll;
+    int bold_chars;
+    int all_bold;
+    int force_term;
+    int linux_mode;
+    int old_style;
+    int only_shadows;
+    int lock_mode;
+    int rainbow_mode;
+    int lambda_mode;
+    int chars_change;
+    int x_mode;
+    int screensaver_mode;
+    int update_delay;
+    char *color;
+    char *message;
+    char *tty;
+} Options;
+
+void parse_options(int argc, char *argv[], Options *opts);
+void print_usage(const char *progname);
+void print_version(void);
